import{K as s,a as i,c as n,b as a,k as t,q as c,ac as r}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Excel 条件判断、计数与汇总","description":"IF、AND、OR、SUMIF、SUMIFS、COUNTIFS、AVERAGEIF、SUBTOTAL 的办公用法，明确状态、时间区间与筛选后的统计口径。","frontmatter":{"title":"Excel 条件判断、计数与汇总","description":"IF、AND、OR、SUMIF、SUMIFS、COUNTIFS、AVERAGEIF、SUBTOTAL 的办公用法，明确状态、时间区间与筛选后的统计口径。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"IF、AND、OR、SUMIF、SUMIFS、COUNTIFS、AVERAGEIF、SUBTOTAL 的办公用法，明确状态、时间区间与筛选后的统计口径。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 公式、相对引用与绝对引用","link":"/tools/office/excel/formulas"},"next":{"text":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","link":"/tools/office/excel/lookup"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 公式、相对引用与绝对引用","link":"/tools/office/excel/formulas"},"next":{"text":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","link":"/tools/office/excel/lookup"}},"headers":[],"relativePath":"tools/office/excel/aggregate.md","filePath":"tools/office/excel/aggregate.md"}'),p={name:"tools/office/excel/aggregate.md"},f=Object.assign(p,{setup(d){const o={path:"/tools/office/excel/aggregate",app:"Excel",title:"算清十月已完成订单的金额",steps:[{tab:"工作表标签",command:"加号",setting:"表名：汇总；原始表：Sales",anchor:"walkthrough-1",surface:"area"},{tab:"公式",command:"插入函数",setting:"函数：SUMIFS；求和区域：Sales[金额]",anchor:"walkthrough-2"},{tab:"数据",command:"筛选",setting:"部门：运营；可见合计：2440",anchor:"walkthrough-3"}]};return(h,e)=>{const l=s("OfficeGuide");return i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"excel-条件判断、计数与汇总",tabindex:"-1"},[t("Excel 条件判断、计数与汇总 "),a("a",{class:"header-anchor",href:"#excel-条件判断、计数与汇总","aria-label":'Permalink to "Excel 条件判断、计数与汇总"'},"​")],-1)),e[1]||(e[1]=a("p",null,[t("本篇使用命名为 "),a("code",null,"Sales"),t(" 的"),a("a",{href:"/tools/office/excel/start#data"},"八条订单"),t("，H 列为金额。所有公式放在数据表之外，例如 "),a("code",null,"汇总"),t(" 工作表，避免在金额列中引用整列自身形成循环引用。")],-1)),c(l,{guide:o}),e[2]||(e[2]=r(`<h2 id="if" tabindex="-1">判断与组合条件 <a class="header-anchor" href="#if" aria-label="Permalink to &quot;判断与组合条件 {#if}&quot;">​</a></h2><p>在订单旁增加“处理提示”列，可以写：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=IF([@状态]=&quot;已完成&quot;,&quot;归档&quot;,&quot;跟进&quot;)</span></span>
<span class="line"><span>=IF(AND([@状态]=&quot;已完成&quot;,[@金额]&gt;=500),&quot;重点复核&quot;,&quot;普通&quot;)</span></span></code></pre></div><p>第一式把取消和待处理都归入“跟进”，未必符合真实流程。更明确的写法是先判断已取消，再判断已完成，剩余为待处理。嵌套超过几层时，考虑用单独的状态映射表，让规则可见而不是埋在长公式里。</p><p><code>AND</code> 要求条件同时满足，<code>OR</code> 要求至少一个满足。比较字符串时注意前后空格和不同写法，“已完成”和“完成”不会自动被当成同一个状态。</p><h2 id="sum" tabindex="-1">单条件与多条件汇总 <a class="header-anchor" href="#sum" aria-label="Permalink to &quot;单条件与多条件汇总 {#sum}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=SUM(Sales[金额])</span></span>
<span class="line"><span>=SUMIF(Sales[部门],&quot;运营&quot;,Sales[金额])</span></span>
<span class="line"><span>=SUMIFS(Sales[金额],Sales[状态],&quot;已完成&quot;)</span></span>
<span class="line"><span>=COUNTIFS(Sales[状态],&quot;已完成&quot;)</span></span>
<span class="line"><span>=AVERAGEIF(Sales[状态],&quot;已完成&quot;,Sales[金额])</span></span></code></pre></div><p>结果分别为 <strong>5120、2440、4060、6、约 676.67</strong>。最后一个值是已完成订单的平均金额，不是平均单价。改变指标名称而不改变公式，会产生“公式正确、业务结论错误”的问题。</p><p><code>SUMIF</code> 的求和区域通常是第三个参数，<code>SUMIFS</code> 的求和区域是第一个参数，初学时很容易写反。所有条件区域与求和区域的行数必须一致。需要让条件可修改时，把“运营”等条件放在一个参数单元格，再引用该单元格。</p><h2 id="dates" tabindex="-1">按完整月份统计 <a class="header-anchor" href="#dates" aria-label="Permalink to &quot;按完整月份统计 {#dates}&quot;">​</a></h2><p>统计 2026 年 10 月已完成金额：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=SUMIFS(Sales[金额],Sales[状态],&quot;已完成&quot;,Sales[日期],&quot;&gt;=&quot;&amp;DATE(2026,10,1),Sales[日期],&quot;&lt;&quot;&amp;DATE(2026,11,1))</span></span></code></pre></div><p>结果为 <strong>3160</strong>。使用“本月第一天及以后、下月第一天之前”可以包含本月最后一天的时间值。若写成小于等于 <code>2026-10-31</code> 的零点，带时分秒的 10 月 31 日白天记录可能被漏掉。</p><p>日期列必须是真实日期/时间值，格式看起来像日期的文本不一定能参与正确比较。用 <code>ISNUMBER</code> 检查练习日期，返回 FALSE 时先修复数据类型。</p><h2 id="filtered" tabindex="-1">筛选后的统计 <a class="header-anchor" href="#filtered" aria-label="Permalink to &quot;筛选后的统计 {#filtered}&quot;">​</a></h2><p>普通 <code>SUM</code> 不会因为筛选隐藏行而自动只计算可见记录。需要随筛选变化的金额合计时，在表外输入：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=SUBTOTAL(109,Sales[金额])</span></span></code></pre></div><p>筛选“状态 = 已完成”后应为 4060。<code>109</code> 表示求和并忽略手工隐藏的行，<code>9</code> 也会排除筛选隐藏行，但对手工隐藏行的处理不同。它仍然是在当前表的可见记录上计算，不自动实现“业务已完成”等规则。</p><h2 id="traps" tabindex="-1">常见陷阱 <a class="header-anchor" href="#traps" aria-label="Permalink to &quot;常见陷阱 {#traps}&quot;">​</a></h2><p>COUNT 统计数值单元格，COUNTA 统计非空内容，不能随意互换。条件中的 <code>*</code> 和 <code>?</code> 可作为通配符，若要匹配字面星号需了解转义。平均值要明确分母，平均订单金额与按数量加权的平均单价不同；本数据全部金额除以全部数量为 <code>5120/20=256</code>，这也包含未完成订单。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>计算技术部门已完成金额，答案是 1620；只取 10 月则为 720。筛选运营部门后，<code>SUBTOTAL</code> 应为 2440，而普通全表 <code>SUM</code> 仍为 5120。解释这些数为什么不同，再进入<a href="/tools/office/excel/pivots">数据透视表</a>用另一种方式核对。</p><h2 id="walkthrough" tabindex="-1">图示跟做：算清十月已完成订单的金额 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：算清十月已完成订单的金额 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先把口径写到汇总表 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先把口径写到汇总表 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：工作表标签 → 加号。</strong></p><p>在工作簿底部点击加号新建汇总表，写明“状态为已完成；日期从 2026-10-01 起，到 2026-11-01 之前”。保留原明细不做删除。确认 Sales 包含金额列，日期可用 ISNUMBER 检查为数值，避免把看起来像日期的文字直接拿来比较。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：输入条件并核对边界 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：输入条件并核对边界 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：公式 → 插入函数。</strong></p><p>在汇总空白格输入本篇按完整月份统计的 SUMIFS 公式，金额区域放第一个参数，状态和日期条件逐对配对。结果应为 3160。再单独统计全部已完成金额，应为 4060；相差 900 正好是 11 月的 O008，能解释差值才算核对通过。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：区分业务条件与界面筛选 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：区分业务条件与界面筛选 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：数据 → 筛选。</strong></p><p>到明细表筛选运营部门，在表外使用 =SUBTOTAL(109,Sales[金额])，结果为 2440。此时普通 =SUM(Sales[金额]) 仍为 5120，原来的十月已完成 SUMIFS 也不会自动因为部门筛选而改变。若希望按部门统计，应把部门写进条件，而不是只操作筛选菜单。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>先判断是范围错、数据类型错还是业务口径错。把错误统一包成 IFERROR(...,0) 会把未修复的数据问题伪装成零金额，汇总前应保留并处理异常。</p>`,35))])}}});export{g as __pageData,f as default};
